<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {scaleLinear,max} from 'd3'
import TrendChart from './TrendChart.vue'
import ProductRanking from './ProductRanking.vue'
import Story from './Story.vue'
import purchaseData from './embedded-data.json'
import {aggregate,filterRows,grouped,monthly,monthKeys,previousPeriod,priceHistory,trailingPeriod} from './analytics.js'
const assetBase=import.meta.env.BASE_URL
const navigationReady=ref(window.parent===window)
const screen=ref('story'),storyPeriod=ref('year'),openedPeriod=ref(null),hostView=ref({offset:0,height:800})
const data=ref(null),error=ref(''),category=ref(null),start=ref(''),end=ref(''),preset=ref('24'),topN=ref(8),search=ref(''),rankingMode=ref('independent'),categoryMetric=ref('spend'),extraMetric=ref('goodsQuantity'),tip=ref(null),pinned=ref(false),tipPosition=ref({}),method=ref(false)
const categoryNames=['База','Фрукты','Овощи','Готовая еда','Сладости','Вода','Напитки','Товары для дома','Снеки','Аптека','Услуги Груши']
const palette=['#5264ff','#f09a40','#25a789','#9568e8','#e26c99','#299ec4','#5f85e5','#947660','#d69235','#ac72c5','#8993a7']
const colors=Object.fromEntries(categoryNames.map((c,i)=>[c,palette[i]]))
const money=v=>v==null?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(v/100)+' ₽'
const number=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(v)
const percent=v=>v==null?'—':number(v)+' %'
const date=v=>v?new Date(v+'T00:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):''
const products=computed(()=>data.value?.products||[]),rows=computed(()=>data.value?.rows||[])
const invalid=computed(()=>!start.value||!end.value||start.value>end.value||(data.value&&(start.value<data.value.audit.minDate||end.value>data.value.audit.maxDate)))
const periodRows=computed(()=>invalid.value?[]:filterRows(rows.value,products.value,start.value,end.value))
const filtered=computed(()=>category.value?periodRows.value.filter(r=>products.value[r.product].category===category.value):periodRows.value)
const metrics=computed(()=>aggregate(filtered.value,products.value))
const total=computed(()=>aggregate(periodRows.value,products.value))
const prev=computed(()=>previousPeriod(start.value||'2024-09-01',end.value||'2026-08-29'))
const prevValid=computed(()=>data.value&&prev.value.start>=data.value.audit.minDate)
const prevMetrics=computed(()=>aggregate(filterRows(rows.value,products.value,prev.value.start,prev.value.end),products.value))
const context=computed(()=>category.value||'Все категории')
const periodLabel=computed(()=>`${date(start.value)} — ${date(end.value)}`)
const keys=computed(()=>data.value?monthKeys(windowStart.value,data.value.audit.maxDate):[])
const windowStart=computed(()=>{if(!data.value)return '2024-09-01';const [y,m]=data.value.audit.maxDate.slice(0,7).split('-').map(Number);return new Date(Date.UTC(y,m-24,1)).toISOString().slice(0,10)})
const trend=computed(()=>monthly(periodRows.value,products.value,keys.value).map(m=>({...m,outside:m.key<start.value.slice(0,7)||m.key>end.value.slice(0,7),discount:m.orders?m.discount:null})))
const trendDisplay=computed(()=>trend.value.map(m=>m.outside?{...m,orders:null,spend:null,discount:null,goodsQuantity:null,average:null,goodsProducts:null,savings:null}:m))
const catData=computed(()=>grouped(periodRows.value,products.value,r=>products.value[r.product].category).sort((a,b)=>(b[categoryMetric.value]||0)-(a[categoryMetric.value]||0)))
const categoryScale=computed(()=>scaleLinear().domain([0,max(catData.value,d=>d[categoryMetric.value])||1]).range([0,100]))
const allGoods=computed(()=>grouped(filtered.value.filter(r=>!products.value[r.product].service),products.value,r=>r.product).map(x=>({...products.value[x.key],...x})))
const qtySorted=computed(()=>[...allGoods.value].sort((a,b)=>b.quantity-a.quantity||b.spend-a.spend))
const spendSorted=computed(()=>[...allGoods.value].sort((a,b)=>b.spend-a.spend||b.quantity-a.quantity))
const qtyRanks=computed(()=>Object.fromEntries(qtySorted.value.map((p,i)=>[p.id,i+1])))
const spendRanks=computed(()=>Object.fromEntries(spendSorted.value.map((p,i)=>[p.id,i+1])))
const qtyList=computed(()=>{let list=rankingMode.value==='spend'?spendSorted.value:qtySorted.value;return list.filter(p=>p.name.toLocaleLowerCase('ru').includes(search.value.toLocaleLowerCase('ru'))).slice(0,+topN.value)})
const spendList=computed(()=>{let list=rankingMode.value==='quantity'?qtySorted.value:spendSorted.value;return list.filter(p=>p.name.toLocaleLowerCase('ru').includes(search.value.toLocaleLowerCase('ru'))).slice(0,+topN.value)})
const leaderDiff=computed(()=>qtySorted.value[0]&&spendSorted.value[0]&&qtySorted.value[0].id!==spendSorted.value[0].id)
const tipHistory=computed(()=>tip.value?priceHistory(filtered.value,products.value,tip.value.id,monthKeys(start.value,end.value)):[])
const kpis=computed(()=>[
 {key:'orders',label:'Доставленные заказы',value:number(total.value.orders),unit:'уникальных заказов',icon:'▤'},
 {key:'spend',label:'Расходы',value:money(total.value.spend),unit:'включая доставку и упаковку',icon:'₽'},
 {key:'discount',label:'Средняя скидка',value:percent(total.value.discount),unit:'на стоимость до скидок',icon:'%'},
 {key:'average',label:'Средний чек',value:money(total.value.average),unit:'на доставленный заказ',icon:'↗'}
])
const extraOptions={goodsQuantity:{label:'Товары',unit:'шт.'},average:{label:'Средний чек',unit:'₽'},goodsProducts:{label:'Уникальные товары',unit:'тов.'},savings:{label:'Экономия',unit:'₽'}}
function delta(key){if(!prevValid.value)return 'Нет полного предыдущего периода';const v=total.value[key],p=prevMetrics.value[key];if(v==null||p==null)return 'Нет покупок для сравнения';if(key==='discount')return `${v-p>=0?'+':''}${number(v-p)} п.п. к прошлому периоду`;if(!p)return v?'База сравнения — 0':'Без изменений';const d=100*(v-p)/p;return `${d>=0?'+':''}${number(d)} % к прошлому периоду`}
function choosePreset(v){preset.value=v;if(!data.value)return;const r=trailingPeriod(v,data.value.audit.minDate,data.value.audit.maxDate);start.value=r.start;end.value=r.end;closeTip()}
function openDashboard(r){if(openedPeriod.value!==r.key){start.value=r.start;end.value=r.end;preset.value={week:'week',month:'1',quarter:'3',year:'12',all:'all'}[r.key];category.value=null;search.value='';openedPeriod.value=r.key}closeTip();screen.value='dashboard'}
function returnToStory(){closeTip();screen.value='story'}
function beforeViewEnter(el){const view=el.id==='dashboard'?'dashboard':'story';if(window.parent!==window){window.parent.postMessage({type:'korzina-view',view},'*');window.parent.postMessage({type:'korzina-scroll',top:0},'*')}else{const hash=view==='dashboard'?'#dashboard':'#story';if(location.hash!==hash)history.pushState({},'',hash);document.documentElement.style.scrollBehavior='auto';window.scrollTo(0,0);requestAnimationFrame(()=>document.documentElement.style.removeProperty('scroll-behavior'))}}
function afterViewEnter(el){el.querySelector('h1')?.focus({preventScroll:true});if(window.parent!==window)requestAnimationFrame(()=>window.parent.postMessage({type:'korzina-scroll',top:0},'*'))}
function navigateTo(view){if(view==='dashboard'){if(!openedPeriod.value)openDashboard({...trailingPeriod(storyPeriod.value,data.value.audit.minDate,data.value.audit.maxDate),key:storyPeriod.value});else screen.value='dashboard'}else returnToStory()}
function hostNavigation(e){if(e.source!==window.parent)return;if(e.data?.type==='korzina-navigation'&&['dashboard','story'].includes(e.data.view)){navigateTo(e.data.view);navigationReady.value=true}if(e.data?.type==='korzina-viewport'&&Number.isFinite(e.data.offset)&&Number.isFinite(e.data.height)&&e.data.height>0&&e.data.height<10000)hostView.value={offset:e.data.offset,height:e.data.height}}
function viewportTop(){return window.parent===window?0:Math.max(0,hostView.value.offset)}
function viewportHeight(){return window.parent===window?window.innerHeight:hostView.value.height}
const tooltipStyle=computed(()=>pinned.value?{right:'24px',top:(viewportTop()+Math.max(12,Math.min(80,viewportHeight()-440)))+'px',maxHeight:(viewportHeight()-24)+'px'}:tipPosition.value)
function ownNavigation(){if(window.parent===window)navigateTo(location.hash==='#dashboard'?'dashboard':'story')}
function chooseCategory(c){category.value=category.value===c?null:c;closeTip()}
function hoverProduct(p,e){if(pinned.value)return;tip.value=p;const rect=e.currentTarget.getBoundingClientRect();const top=viewportTop(),height=viewportHeight();tipPosition.value={top:Math.max(top+12,Math.min(rect.top,top+height-440))+'px',left:Math.max(12,Math.min(rect.right+12,window.innerWidth-360))+'px',maxHeight:(height-24)+'px'}}
function leaveProduct(){if(!pinned.value)tip.value=null}
function selectProduct(p){tip.value=p;pinned.value=true;tipPosition.value={right:'24px',top:'100px'}}
function closeTip(){tip.value=null;pinned.value=false}
function onKey(e){if(e.key==='Escape')closeTip()}
function exportCSV(){const lines=[['Товар','Категория','Количество','Расходы_руб','Заказов','Цена_ед_руб'],...spendSorted.value.map(p=>[p.name,p.category,p.quantity,p.spend/100,p.orders,p.unitPrice/100])];const csv='\ufeff'+lines.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Покупки_'+start.value+'_'+end.value+'.csv';a.click();URL.revokeObjectURL(a.href)}
onMounted(async()=>{window.addEventListener('keydown',onKey);try{data.value=purchaseData;choosePreset('12');window.addEventListener('message',hostNavigation);window.addEventListener('popstate',ownNavigation);if(window.parent===window)ownNavigation();else window.parent.postMessage({type:'korzina-navigation-request'},'*')}catch(e){error.value='Не удалось загрузить данные. Запустите проект через HTTP-сервер. '+e.message}})
onBeforeUnmount(()=>{window.removeEventListener('keydown',onKey);window.removeEventListener('message',hostNavigation);window.removeEventListener('popstate',ownNavigation)})
</script>
<template>
 <div v-if="error" class="loading">{{error}}</div><div v-else-if="!data||!navigationReady" class="loading">Загружаем историю покупок…</div>
 <template v-else>
 <header class="site-header"><button class="brand" @click="returnToStory"><span class="brand-mark">▥</span>корзина<span class="brand-divider"></span><span class="brand-sub">ваши покупки</span></button><nav v-if="screen==='dashboard'"><button class="back-to-story" @click="returnToStory">← Вернуться к истории</button></nav><span class="dataset-badge">{{screen==='dashboard'?'Ваша корзина':'История ваших покупок'}}</span></header>
 <Transition name="experience" mode="out-in" @before-enter="beforeViewEnter" @after-enter="afterViewEnter">
 <Story v-if="screen==='story'" key="story" :data="data" :colors="colors" v-model:period="storyPeriod" @open-dashboard="openDashboard"/>
 <main v-else key="dashboard" id="dashboard">
 <div class="page-heading"><div><div class="eyebrow">ТЕПЕРЬ ПОСМОТРИМ БЛИЖЕ</div><h1 tabindex="-1">Какая история интересна вам?</h1><p>Меняйте период, выбирайте категории и сравнивайте товары. Все детали — здесь.</p></div></div>
 <div class="filter-bar"><div class="filter-caption"><span>Период анализа</span><small>По дате заказа</small></div><div class="presets"><button v-for="[v,label] in [['week','Неделя'],['1','Месяц'],['3','Квартал'],['12','Год'],['24','2 года'],['all','Весь период']]" :key="v" :class="{active:preset===v}" @click="choosePreset(v)">{{label}}</button></div><div class="date-range"><input aria-label="Начало периода" type="date" v-model="start" :min="data.audit.minDate" :max="data.audit.maxDate" @change="preset='custom';closeTip()"><span>—</span><input aria-label="Конец периода" type="date" v-model="end" :min="data.audit.minDate" :max="data.audit.maxDate" @change="preset='custom';closeTip()"></div><button class="filter-category" @click="category=null;closeTip()"><i :style="{background:category?colors[category]:'#316b54'}"></i>{{context}}<span v-if="category">×</span></button></div>
 <p v-if="invalid" class="alert" role="alert">Выберите даты в пределах истории покупок. Начало периода должно быть не позже окончания.</p>
 <div class="context-line"><span>{{periodLabel}} <b>· Вся корзина</b></span><span>Только доставленные заказы <span class="info-icon" title="111 строк отменённых заказов исключены из расчётов">i</span></span></div>
 <div class="kpi-grid"><article v-for="k in kpis" :key="k.key" class="kpi"><div class="kpi-label">{{k.label}}<span>{{k.icon}}</span></div><strong>{{k.value}}</strong><span class="kpi-unit">{{k.unit}}</span><small class="delta">{{delta(k.key)}}</small></article></div>
 <div class="secondary-metrics"><span><b>{{number(total.goodsQuantity)}}</b> шт. товаров</span><span><b>{{number(total.goodsProducts)}}</b> уникальных товаров</span><span><b>{{total.categories}}</b> категорий с покупками</span><span><b>{{money(total.savings)}}</b> экономии</span><span class="period-note">за выбранный период</span></div>
 <section id="dynamics" class="panel"><div class="section-top"><div><div class="eyebrow">У КАЖДОЙ КОРЗИНЫ СВОЙ РИТМ</div><h2>Ваши покупки, месяц за месяцем</h2><p>Последние два года · сентябрь 2024 — август 2026</p></div><span class="scope">Вся корзина</span></div>
 <div class="chart-note">Здесь показан выбранный период на шкале последних двух лет. За пределами периода линия прерывается. Август 2026 — по 29 числу.</div>
 <div class="trend-grid"><article><div class="chart-heading"><h3>Заказы</h3><span>уникальных / месяц</span></div><TrendChart :data="trendDisplay" metric="orders" color="#5264ff" unit="заказов" title="Заказы за последние 24 месяца"/></article><article><div class="chart-heading"><h3>Расходы</h3><span>₽ / месяц</span></div><TrendChart :data="trendDisplay" metric="spend" color="#ed8b49" unit="₽" title="Расходы за последние 24 месяца"/></article><article><div class="chart-heading"><h3>Средняя скидка</h3><span>% от стоимости до скидки</span></div><TrendChart :data="trendDisplay" metric="discount" color="#9969df" unit="%" title="Средняя скидка за последние 24 месяца"/></article></div>
 <div class="extra-trend"><div class="chart-heading"><h3>Ещё один взгляд</h3><select v-model="extraMetric" aria-label="Дополнительная метрика динамики"><option v-for="(o,key) in extraOptions" :key="key" :value="key">{{o.label}} · {{o.unit}}</option></select></div><TrendChart :data="trendDisplay" :metric="extraMetric" color="#159e8e" :unit="extraOptions[extraMetric].unit" :title="extraOptions[extraMetric].label"/></div>
 <p v-if="end<windowStart" class="alert">Выбранный период раньше окна последних 24 месяцев. Показатели и рейтинги рассчитаны по фильтру; для динамики выберите период в окне или изучите категорию ниже.</p>
 </section>
 <section id="categories" class="panel"><div class="section-top"><div><div class="eyebrow">КУДА УХОДЯТ ДЕНЬГИ</div><h2>Начните с интересной категории</h2><p>Все категории за {{periodLabel}}. Выберите категорию, чтобы увидеть её покупки.</p></div><label>Сортировать по <select v-model="categoryMetric" aria-label="Метрика категорий"><option value="spend">Расходам</option><option value="quantity">Количеству единиц</option><option value="orders">Заказам</option><option value="average">Чеку категории</option></select></label></div>
 <div v-if="category" class="selection-banner"><span><i :style="{background:colors[category]}"></i>Выбрана категория: <b>{{category}}</b> · {{total.spend?percent(100*metrics.spend/total.spend):'—'}} общих расходов</span><button @click="category=null;closeTip()">Сбросить ×</button></div>
 <div v-if="category" class="category-selected-metrics"><div><span>Расходы категории</span><b>{{money(metrics.spend)}}</b></div><div><span>{{category==='Услуги Груши'?'Услуг':'Купили товаров'}}</span><b>{{number(metrics.quantity)}} {{category==='Услуги Груши'?'ед.':'шт.'}}</b></div><div><span>Заказов с категорией</span><b>{{metrics.orders}}</b></div><div><span>На категорию в одном заказе</span><b>{{money(metrics.average)}}</b></div></div>
 <div class="category-layout"><div class="category-bars"><div class="chart-heading"><h3>{{{spend:'Расходы',quantity:'Количество единиц',orders:'Заказы',average:'Чек категории'}[categoryMetric]}}</h3><span>Все категории</span></div><button v-for="c in catData" :key="c.key" :class="['category-bar-row',{selected:category===c.key,muted:category&&category!==c.key}]" @click="chooseCategory(c.key)"><span class="bar-name"><i :style="{background:colors[c.key]}"></i>{{c.key}}</span><span class="bar-track"><svg viewBox="0 0 100 12" preserveAspectRatio="none"><rect :width="categoryScale(c[categoryMetric])" height="12" rx="3" :fill="colors[c.key]"/></svg></span><b>{{['spend','average'].includes(categoryMetric)?money(c[categoryMetric]):number(c[categoryMetric])}}</b></button></div>
 <div class="table-scroll"><table class="category-table"><thead><tr><th>Категория</th><th>Расходы, ₽</th><th>Доля</th><th>Единиц</th><th>Заказов</th><th>Чек, ₽</th></tr></thead><tbody><tr v-for="c in catData" :key="c.key" :class="{selected:category===c.key}"><td><button @click="chooseCategory(c.key)"><i :style="{background:colors[c.key]}"></i>{{c.key}}</button></td><td>{{money(c.spend)}}</td><td>{{total.spend?percent(100*c.spend/total.spend):'—'}}</td><td>{{number(c.quantity)}}</td><td>{{c.orders}}</td><td>{{money(c.average)}}</td></tr></tbody></table><div v-if="!catData.length" class="empty">В этом периоде нет покупок.</div></div></div>
 <p class="fine-print">Чек категории = расходы на категорию / уникальные заказы с этой категорией. Заказы разных категорий пересекаются и не складываются. Для «Услуг Груши» единицы — доставка и упаковка.</p>
 <div class="category-trend"><div class="chart-heading"><h3>{{category?'Динамика категории «'+category+'»':'Динамика всех категорий'}}</h3><span>Выбранный период</span></div><div class="two-trends"><article><h4>Расходы · ₽</h4><TrendChart :data="monthly(filtered,products,monthKeys(start,end))" metric="spend" :color="category?colors[category]:'#316b54'" unit="₽" title="Помесячные расходы категории"/></article><article><h4>{{category==='Услуги Груши'?'Услуги · ед.':'Товары · шт.'}}</h4><TrendChart :data="monthly(filtered,products,monthKeys(start,end))" :metric="category==='Услуги Груши'?'quantity':'goodsQuantity'" :color="category?colors[category]:'#316b54'" unit="ед." title="Помесячное количество категории"/></article></div></div>
 </section>
 <section id="assortment" class="panel assortment"><div class="section-top"><div><div class="eyebrow">ЗАГЛЯНЕМ ВНУТРЬ</div><h2>Товары в штуках и рублях</h2><p>Посмотрите, что вы берёте чаще и на что тратите больше.</p></div><span class="scope">{{context}} · {{allGoods.length}} товаров</span></div>
 <div v-if="qtySorted.length" class="insight"><span>↗</span><p v-if="leaderDiff">Лидер по количеству — <b>{{qtySorted[0].name}}</b>. По расходам — <b>{{spendSorted[0].name}}</b>.</p><p v-else>Лидер и по количеству, и по расходам — <b>{{qtySorted[0].name}}</b>.</p></div>
 <div class="assortment-controls"><label class="search"><span>⌕</span><input v-model="search" placeholder="Найти товар" aria-label="Найти товар"></label><label>Сравнение <select v-model="rankingMode"><option value="independent">У каждого рейтинга свои лидеры</option><option value="quantity">Одни товары: больше покупаем</option><option value="spend">Одни товары: больше тратим</option></select></label><label>Показать <select v-model="topN"><option :value="8">Топ-8</option><option :value="15">Топ-15</option><option :value="30">Топ-30</option><option :value="500">Все товары</option></select></label></div>
 <div class="rankings"><ProductRanking :items="qtyList" metric="quantity" title="Берём больше" subtitle="Количество купленных единиц товара" :colors="colors" :other-ranks="spendRanks" @hover="hoverProduct" @leave="leaveProduct" @select="selectProduct"/><ProductRanking :items="spendList" metric="spend" title="Тратим больше" subtitle="Расходы после скидок" :colors="colors" :other-ranks="qtyRanks" @hover="hoverProduct" @leave="leaveProduct" @select="selectProduct"/></div>
 <div class="section-foot"><span>Наведите на товар, чтобы увидеть цену и её историю. Нажмите, чтобы закрепить карточку.</span><span>Доставка и упаковка исключены из рейтингов.</span></div>
 </section>
 <section class="methodology"><button @click="method=!method" :aria-expanded="method"><span>О цифрах этой истории</span><span>{{method?'−':'+'}}</span></button><div v-if="method" class="method-content"><p>Одна строка — позиция в заказе. Датасет: {{date(data.audit.minDate)}} — {{date(data.audit.maxDate)}}. Обработано {{data.audit.sourceRows}} строк; {{data.audit.acceptedRows}} доставленных. {{data.audit.excludedStatuses['отменен']}} строк отменённых заказов исключены. Дубликатов, отрицательных значений, пропусков обязательных полей и расхождений сумм нет. Возвраты отдельным статусом отсутствуют.</p><p><b>Расходы</b> = Σ amount = Σ (price_discounted × quantity). <b>Экономия</b> = Σ ((price − price_discounted) × quantity). <b>Средняя скидка</b> = 100 × экономия / Σ (price × quantity). Поле discount — рубли на единицу, а не проценты. Деньги хранятся в копейках.</p><p><b>Заказы</b> = число уникальных order_id. <b>Средний чек</b> = расходы / уникальные заказы; в категории — расходы этой категории на заказ с ней. <b>Штуки товаров</b> = Σ quantity без доставки и упаковки. Единица — купленная упаковка или позиция, а не килограмм и не содержимое упаковки. <b>Цена единицы</b> = Σ amount / Σ quantity; помесячная цена взвешена по количеству. Нет покупки — нет цены; линия прерывается.</p><p>Изменения сравнивают с непосредственно предшествующим периодом такой же длины в днях: {{date(prev.start)}} — {{date(prev.end)}}. Сравнение скрыто, если этот период выходит за начало данных. Крайние месяцы датасета неполные. Внутри наблюдаемого периода месяц без заказов считается нулём; полноту выгрузки извне установить нельзя. Даты вне диапазона источника недоступны.</p><p>Изображения привязаны через items/positions.csv: 385 точных совпадений, 115 после замены бренда «Груши/Груша» на «Лавки/Лавка». Все 500 позиций сопоставлены. Адрес, время доставки и другие лишние персональные поля не публикуются.</p></div></section>
 <footer><span class="brand-footer">корзина<span> / история повседневных покупок</span></span><span>Ваши покупки · данные по 29 августа 2026 </span></footer>
 </main>
 </Transition>
 <aside v-if="tip" :style="tooltipStyle" class="product-tooltip" :class="{pinned}" role="dialog" aria-label="Карточка товара"><button class="tooltip-close" @click="closeTip" aria-label="Закрыть карточку">×</button><div class="tooltip-top"><img v-if="tip.image" :src="tip.imageData||`${assetBase}items/${tip.image}`" :alt="tip.name"><div><span class="eyebrow">{{tip.category}}</span><h3>{{tip.name}}</h3></div></div><div class="tooltip-metrics"><div><span>Количество</span><b>{{number(tip.quantity)}} шт.</b></div><div><span>Расходы</span><b>{{money(tip.spend)}}</b></div><div><span>Заказов с товаром</span><b>{{tip.orders}}</b></div><div><span>Цена единицы</span><b>{{money(tip.unitPrice)}}</b></div></div><div class="tooltip-chart-title">Цена единицы по месяцам · ₽</div><TrendChart :data="tipHistory" metric="value" :color="colors[tip.category]" unit="₽" :small="true" title="Динамика цены единицы товара"/><p>Средняя цена купленной единицы в месяце. Пробел в линии — нет покупок.</p><small>{{periodLabel}}</small><span v-if="pinned" class="pinned-label">Карточка закреплена · Esc для закрытия</span></aside>
 </template>
</template>
